3	/**
4	 * Derives the owner's membership level: a number from 1 to 3 fixed at creation. It
5	 * starts at 1, gains 1 when an email is on file, gains 1 when the owner had no
6	 * namesakes at creation (namesakeCount is 0), and is capped at 3 (level 4 is reserved
7	 * for tenure). The value is a pure function of those two fields, so it needs no stored
8	 * state.
9	 */
10	public final class MembershipLevel {
11	
12	    private static final int MAX = 3;
13	
14	    private MembershipLevel() {
15	    }
16	
17	    public static int of(Integer namesakeCount, String email) {
18	        int level = 1;
19	        if (email != null && !email.isBlank()) {
20	            level++;
21	        }
22	        if (namesakeCount != null && namesakeCount == 0) {
23	            level++;
24	        }
25	        return Math.min(level, MAX);
26	    }
27	}
