8	/**
9	 * Rewrites the create body's address into a canonical form: trimmed with collapsed
10	 * whitespace, upper-cased, and common street-type abbreviations expanded (ST-&gt;STREET,
11	 * RD-&gt;ROAD, AVE-&gt;AVENUE). Runs before {@link BuildOwner}, so the persisted and
12	 * returned value is already normalized and every later address comparison (household
13	 * duplicate detection and the shared household id) sees the same normalized string.
14	 * {@link RequireOwnerFields} runs first and rejects a whitespace-only address, so the
15	 * value here is never blank.
16	 */
17	public class NormalizeOwnerAddress {
18	
19	    private static final Map<String, String> ABBREVIATIONS =
20	            Map.of("ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
21	
22	    public void service(@Val OwnerFieldsDto request) {
23	        String[] words = request.getAddress().trim().toUpperCase().split("\\s+");
24	        StringBuilder normalized = new StringBuilder();
25	        for (String word : words) {
26	            if (normalized.length() > 0) {
27	                normalized.append(' ');
28	            }
29	            normalized.append(ABBREVIATIONS.getOrDefault(word, word));
30	        }
31	        request.setAddress(normalized.toString());
32	    }
33	}
