17	    private HouseholdTier() {
18	    }
19	
20	    public static boolean isGold(Owner owner, OwnerRepository ownerRepository) {
21	        String householdId = HouseholdId.of(owner.getLastName(), owner.getAddress());
22	        long members = ownerRepository.findAll().stream()
23	                .filter(o -> householdId.equals(HouseholdId.of(o.getLastName(), o.getAddress())))
24	                .count();
25	        return members >= GOLD_THRESHOLD;
26	    }
