1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
7	import org.springframework.samples.petclinic.rest.escalation.DuplicateHouseholdException;
8	
9	/**
10	 * Rejects a create body whose last name and address already belong to another owner
11	 * (compared case-insensitively with collapsed whitespace), so the endpoint responds
12	 * 409 — unless the request opts in with {@code sharesHousehold} true.
13	 */
14	public class RejectDuplicateHousehold {
15	
16	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
17	            throws DuplicateHouseholdException {
18	        if (Boolean.TRUE.equals(request.getSharesHousehold())) {
19	            return;
20	        }
21	        String lastName = key(request.getLastName());
22	        String address = key(request.getAddress());
23	        for (Owner existing : ownerRepository.findAll()) {
24	            if (lastName.equals(key(existing.getLastName())) && address.equals(key(existing.getAddress()))) {
25	                throw new DuplicateHouseholdException(request.getLastName(), request.getAddress());
26	            }
27	        }
28	    }
29	
30	    private static String key(String value) {
31	        return value == null ? "" : value.trim().replaceAll("\\s+", " ").toLowerCase();
32	    }
33	}
